package steps;
import framework.App;
import io.cucumber.java.After;
import io.cucumber.java.en.Then;
import io.cucumber.java.en.When;
public final class UserApiSteps {
  private final App app = new App();
  @When("I request the users collection")
  public void requestUsers() { app.userService().requestUsers(); }
  @Then("the users response is successful")
  public void successful() { app.userService().verifyUsersResponse(); }
  @After
  public void close() { app.close(); }
}
